{
  "hooks": {
    "Stop": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "scripts/run-folkways hook x"
          },
          {
            "type": "command",
            "command": "echo folkways hook x"
          },
          {
            "type": "command",
            "command": "npx folkways hook x"
          },
          {
            "type": "command",
            "command": "scripts/team.sh && node_modules/.bin/folkways hook x"
          },
          {
            "type": "command",
            "command": "node_modules/.bin/folkways hooks x"
          },
          {
            "type": "command",
            "command": "node_modules/.bin/folkways-hook x"
          },
          {
            "type": "command",
            "command": "scripts/team.sh && \"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook x"
          },
          {
            "type": "command",
            "command": ""
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook session-start"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook context-band"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook git-guard"
          }
        ]
      }
    ],
    "PostToolBatch": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook context-band"
          }
        ]
      }
    ],
    "PreCompact": [
      {
        "hooks": [
          {
            "type": "command",
            "command": "\"${CLAUDE_PROJECT_DIR:-.}\"/node_modules/.bin/folkways-hook precompact"
          }
        ]
      }
    ]
  },
  "disableAllHooks": false,
  "permissions": {
    "ask": [
      "Bash(git push:*)"
    ]
  }
}
